import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import test from "node:test";

// The fixture expectations are vendored verbatim from the fixed SPEC
// candidate da80a6d6387cde5ec4b0f6c2e57483b07ccc2104 (spec task
// labs-credit-card-payoff-calculator-spec-20261109, draft PR #137);
// they were authored with the SPEC, never generated by this product.

import { buildReport, formatMoney, run } from "../public/js/core/payoff.mjs";

const fixtures = JSON.parse(
  await readFile(new URL("./fixtures.json", import.meta.url), "utf8"),
);

for (const fixture of fixtures.cases.filter((entry) => entry.kind === "core")) {
  test(`fixture ${fixture.id}`, () => {
    assert.deepStrictEqual(run(fixture.input), fixture.expected);
  });
}

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false, "expected a failure outcome");
  return outcome.error;
}

const VALID_PAYMENT = {
  balance: "1200.00",
  aprPercent: "12",
  mode: "payment",
  monthlyPayment: "110.00",
  targetMonths: null,
};

test("schema: non-object, array, extra key, missing key, wrong type, accessor", () => {
  assert.deepStrictEqual(errorOf(null), { code: "SCHEMA", field: null, row: null });
  assert.deepStrictEqual(errorOf([1, 2]), { code: "SCHEMA", field: null, row: null });
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, extra: "x" }),
    { code: "SCHEMA", field: "extra", row: null },
  );
  const missing = { ...VALID_PAYMENT };
  delete missing.aprPercent;
  assert.deepStrictEqual(errorOf(missing), { code: "SCHEMA", field: "aprPercent", row: null });
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: 1200 }),
    { code: "SCHEMA", field: "balance", row: null },
  );
  const accessor = { ...VALID_PAYMENT };
  Object.defineProperty(accessor, "balance", {
    enumerable: true,
    get() {
      return "1200.00";
    },
  });
  assert.deepStrictEqual(errorOf(accessor), { code: "SCHEMA", field: "balance", row: null });
});

test("schema: inactive field must be null, active field must be a string", () => {
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, targetMonths: "24" }),
    { code: "SCHEMA", field: "targetMonths", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, monthlyPayment: null }),
    { code: "SCHEMA", field: "monthlyPayment", row: null },
  );
  assert.deepStrictEqual(
    errorOf({
      balance: "1200.00", aprPercent: "12", mode: "months",
      monthlyPayment: "110.00", targetMonths: "12",
    }),
    { code: "SCHEMA", field: "monthlyPayment", row: null },
  );
  assert.deepStrictEqual(
    errorOf({
      balance: "1200.00", aprPercent: "12", mode: "months",
      monthlyPayment: null, targetMonths: null,
    }),
    { code: "SCHEMA", field: "targetMonths", row: null },
  );
});

test("capacity, unicode, empty, format and range errors in SPEC order", () => {
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "1234567890123" }),
    { code: "INPUT_LIMIT", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, aprPercent: "123.456" }),
    { code: "INPUT_LIMIT", field: "aprPercent", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "1\uD800" }),
    { code: "UNICODE", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "" }),
    { code: "EMPTY", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "1,200.00" }),
    { code: "MONEY_FORMAT", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "01.00" }),
    { code: "MONEY_FORMAT", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, aprPercent: ".5" }),
    { code: "PERCENT_FORMAT", field: "aprPercent", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, aprPercent: "12.345" }),
    { code: "PERCENT_FORMAT", field: "aprPercent", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, mode: "weekly" }),
    { code: "ENUM", field: "mode", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "0" }),
    { code: "RANGE", field: "balance", row: null },
  );
  assert.deepStrictEqual(
    errorOf({ ...VALID_PAYMENT, balance: "0.00" }),
    { code: "RANGE", field: "balance", row: null },
  );
});

test("target months grammar and range", () => {
  const monthsInput = (targetMonths) => ({
    balance: "1200.00", aprPercent: "12", mode: "months",
    monthlyPayment: null, targetMonths,
  });
  assert.deepStrictEqual(
    errorOf(monthsInput("1.5")),
    { code: "INTEGER_FORMAT", field: "targetMonths", row: null },
  );
  assert.deepStrictEqual(
    errorOf(monthsInput("12.0")),
    { code: "INPUT_LIMIT", field: "targetMonths", row: null },
  );
  assert.deepStrictEqual(
    errorOf(monthsInput("0")),
    { code: "RANGE", field: "targetMonths", row: null },
  );
  assert.deepStrictEqual(
    errorOf(monthsInput("601")),
    { code: "RANGE", field: "targetMonths", row: null },
  );
  const atCap = run({
    balance: "600.00", aprPercent: "0", mode: "months",
    monthlyPayment: null, targetMonths: "600",
  });
  assert.equal(atCap.ok, true);
  assert.equal(atCap.result.months, 600);
  assert.equal(atCap.result.requiredPaymentCents, 100);
  const atMin = run(monthsInput("1"));
  assert.equal(atMin.ok, true);
  assert.equal(atMin.result.months, 1);
});

test("boundary values: maximum balance and APR 99.99", () => {
  const maxApr = run({
    balance: "100.00", aprPercent: "99.99", mode: "payment",
    monthlyPayment: "200.00", targetMonths: null,
  });
  assert.equal(maxApr.ok, true);
  assert.equal(maxApr.result.months, 1);
  assert.equal(maxApr.result.rows[0].interestCents, 833);
  const aprMaxOk = run({ ...VALID_PAYMENT, aprPercent: "99.99", monthlyPayment: "999999999.99" });
  assert.equal(aprMaxOk.ok, true);
});

test("identities hold across a spread of valid plans", () => {
  const plans = [
    { balance: "50000.00", aprPercent: "15", mode: "payment", monthlyPayment: "3000.00", targetMonths: null },
    { balance: "999.99", aprPercent: "22.8", mode: "payment", monthlyPayment: "50.00", targetMonths: null },
    { balance: "250000.00", aprPercent: "18.5", mode: "months", monthlyPayment: null, targetMonths: "36" },
    { balance: "100.00", aprPercent: "0", mode: "months", monthlyPayment: null, targetMonths: "7" },
    { balance: "123456.78", aprPercent: "9.99", mode: "months", monthlyPayment: null, targetMonths: "600" },
  ];
  for (const plan of plans) {
    const outcome = run(plan);
    assert.equal(outcome.ok, true, JSON.stringify(plan));
    const result = outcome.result;
    const balanceCents = Math.round(Number(plan.balance) * 100);
    const principalSum = result.rows.reduce((sum, row) => sum + row.principalCents, 0);
    const interestSum = result.rows.reduce((sum, row) => sum + row.interestCents, 0);
    const paymentSum = result.rows.reduce((sum, row) => sum + row.paymentCents, 0);
    assert.equal(principalSum, balanceCents);
    assert.equal(interestSum, result.totalInterestCents);
    assert.equal(paymentSum, result.totalPaidCents);
    assert.equal(result.totalPaidCents, balanceCents + result.totalInterestCents);
    assert.equal(result.rows.length, result.months);
    assert.equal(result.rows.at(-1).balanceCents, 0);
    assert.equal(result.rows.at(-1).paymentCents, result.finalPaymentCents);
    if (plan.mode === "months") {
      assert.ok(result.months <= Number(plan.targetMonths));
      assert.equal(result.targetMonths, Number(plan.targetMonths));
    }
  }
});

test("payment one cent above the first interest still pays off", () => {
  const outcome = run({
    balance: "5000.00", aprPercent: "24", mode: "payment",
    monthlyPayment: "100.01", targetMonths: null,
  });
  assert.equal(outcome.ok, true);
  assert.ok(outcome.result.months > 1);
});

test("formatMoney groups thousands and fixes two decimals", () => {
  assert.equal(formatMoney(0), "0.00");
  assert.equal(formatMoney(5), "0.05");
  assert.equal(formatMoney(100), "1.00");
  assert.equal(formatMoney(127711), "1,277.11");
  assert.equal(formatMoney(100000), "1,000.00");
  assert.equal(formatMoney(99999999999), "999,999,999.99");
});

test("report bytes follow the pinned serialisation exactly", () => {
  const result = {
    mode: "payment",
    months: 1,
    totalInterestCents: 0,
    totalPaidCents: 100,
    finalPaymentCents: 100,
    rows: [{ month: 1, paymentCents: 100, interestCents: 0, principalCents: 100, balanceCents: 0 }],
  };
  const report = buildReport(result);
  assert.equal(report.ok, true);
  const expectedText =
    '{"finalPaymentCents":100,"mode":"payment","months":1,"rows":[' +
    '{"balanceCents":0,"interestCents":0,"month":1,"paymentCents":100,"principalCents":100}' +
    '],"totalInterestCents":0,"totalPaidCents":100}\n';
  assert.equal(report.text, expectedText);
  assert.equal(report.bytes.byteLength, Buffer.byteLength(expectedText, "utf8"));
  assert.equal(report.bytes[0], 0x7b); // "{" — no BOM
  const digest = createHash("sha256").update(report.bytes).digest("hex");
  assert.equal(digest, createHash("sha256").update(expectedText, "utf8").digest("hex"));
  const again = buildReport(result);
  assert.deepStrictEqual(again.bytes, report.bytes);
});
